impl ::flatbuffers::Verifiable for ERMGate<'_> {
    #[inline]
    fn run_verifier(
        v: &mut ::flatbuffers::Verifier, pos: usize
    ) -> Result<(), ::flatbuffers::InvalidFlatbuffer> {
        v.visit_table(pos)?
            .visit_field::<f64>("TOLERANCE", Self::VT_TOLERANCE, false)?
            .visit_field::<f64>("TAIL_LIMIT", Self::VT_TAIL_LIMIT, false)?
            .visit_field::<u32>("MINIMUM_SAMPLES", Self::VT_MINIMUM_SAMPLES, false)?
            .visit_field::<u32>("MINIMUM_OBJECTS", Self::VT_MINIMUM_OBJECTS, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<&str>>("RULE", Self::VT_RULE, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'_, f64>>>("NOMINAL", Self::VT_NOMINAL, false)?
            .finish();
        Ok(())
    }
}

