pub struct ERMGateBuilder<'a: 'b, 'b, A: ::flatbuffers::Allocator + 'a> {
    fbb_: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    start_: ::flatbuffers::WIPOffset<::flatbuffers::TableUnfinishedWIPOffset>,
}

impl<'a: 'b, 'b, A: ::flatbuffers::Allocator + 'a> ERMGateBuilder<'a, 'b, A> {
    #[inline]
    pub fn add_TOLERANCE(&mut self, TOLERANCE: f64) {
        self.fbb_.push_slot::<f64>(ERMGate::VT_TOLERANCE, TOLERANCE, 0.05);
    }

    #[inline]
    pub fn add_TAIL_LIMIT(&mut self, TAIL_LIMIT: f64) {
        self.fbb_.push_slot::<f64>(ERMGate::VT_TAIL_LIMIT, TAIL_LIMIT, 0.01);
    }

    #[inline]
    pub fn add_MINIMUM_SAMPLES(&mut self, MINIMUM_SAMPLES: u32) {
        self.fbb_.push_slot::<u32>(ERMGate::VT_MINIMUM_SAMPLES, MINIMUM_SAMPLES, 30);
    }

    #[inline]
    pub fn add_MINIMUM_OBJECTS(&mut self, MINIMUM_OBJECTS: u32) {
        self.fbb_.push_slot::<u32>(ERMGate::VT_MINIMUM_OBJECTS, MINIMUM_OBJECTS, 3);
    }

    #[inline]
    pub fn add_RULE(&mut self, RULE: ::flatbuffers::WIPOffset<&'b  str>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(ERMGate::VT_RULE, RULE);
    }

    #[inline]
    pub fn add_NOMINAL(&mut self, NOMINAL: ::flatbuffers::WIPOffset<::flatbuffers::Vector<'b , f64>>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(ERMGate::VT_NOMINAL, NOMINAL);
    }

    #[inline]
    pub fn new(_fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>) -> ERMGateBuilder<'a, 'b, A> {
        let start = _fbb.start_table();
        ERMGateBuilder {
            fbb_: _fbb,
            start_: start,
        }
    }

    #[inline]
    pub fn finish(self) -> ::flatbuffers::WIPOffset<ERMGate<'a>> {
        let o = self.fbb_.end_table(self.start_);
        ::flatbuffers::WIPOffset::new(o.value())
    }
}

