        if let Some(x) = args.HORIZONS_DAYS { builder.add_HORIZONS_DAYS(x); }
        if let Some(x) = args.STRATA_SETTINGS { builder.add_STRATA_SETTINGS(x); }
        if let Some(x) = args.PROPAGATOR { builder.add_PROPAGATOR(x); }
        if let Some(x) = args.BASIS_TEXT { builder.add_BASIS_TEXT(x); }
        if let Some(x) = args.CANDIDATE { builder.add_CANDIDATE(x); }
        if let Some(x) = args.CALIBRATION_VERSION { builder.add_CALIBRATION_VERSION(x); }
        if let Some(x) = args.ID { builder.add_ID(x); }
        builder.add_POOLED(args.POOLED);
        builder.add_BASIS(args.BASIS);
