    pub const VT_VELOCITY_M_S: ::flatbuffers::VOffsetT = 8;
    pub const VT_COVARIANCE: ::flatbuffers::VOffsetT = 10;
    pub const VT_COVARIANCE_TERMS: ::flatbuffers::VOffsetT = 12;
    pub const VT_COVARIANCE_AXES: ::flatbuffers::VOffsetT = 14;
    pub const VT_SAMPLES: ::flatbuffers::VOffsetT = 16;
    pub const VT_INTERPOLATION_DEGREE: ::flatbuffers::VOffsetT = 18;

