    #[allow(unused_mut)]
    pub fn create<'bldr: 'args, 'args: 'mut_bldr, 'mut_bldr, A: ::flatbuffers::Allocator + 'bldr>(
        _fbb: &'mut_bldr mut ::flatbuffers::FlatBufferBuilder<'bldr, A>,
        args: &'args ERMFitSettingsArgs<'args>
    ) -> ::flatbuffers::WIPOffset<ERMFitSettings<'bldr>> {
        let mut builder = ERMFitSettingsBuilder::new(_fbb);
        builder.add_REJECT_SIGMA(args.REJECT_SIGMA);
        builder.add_FLOOR_KM(args.FLOOR_KM);
        builder.add_TOLERANCE(args.TOLERANCE);
        builder.add_HALF_LIFE_HOURS(args.HALF_LIFE_HOURS);
        builder.add_SIGMA_VELOCITY_KM_S(args.SIGMA_VELOCITY_KM_S);
        builder.add_BSTAR(args.BSTAR);
        builder.add_STEP_S(args.STEP_S);
        builder.add_ELEMENT_SET_NO(args.ELEMENT_SET_NO);
        if let Some(x) = args.OBJECT_ID { builder.add_OBJECT_ID(x); }
        if let Some(x) = args.OBJECT_NAME { builder.add_OBJECT_NAME(x); }
        if let Some(x) = args.COMMENT { builder.add_COMMENT(x); }
        if let Some(x) = args.CLASSIFICATION { builder.add_CLASSIFICATION(x); }
        if let Some(x) = args.CREATION_DATE { builder.add_CREATION_DATE(x); }
        if let Some(x) = args.ORIGINATOR { builder.add_ORIGINATOR(x); }
        builder.add_EPHEMERIS_STREAM(args.EPHEMERIS_STREAM);
        builder.add_MAX_ITERATIONS(args.MAX_ITERATIONS);
        if let Some(x) = args.SIGMA_RTN_KM { builder.add_SIGMA_RTN_KM(x); }
        if let Some(x) = args.EPOCH { builder.add_EPOCH(x); }
        if let Some(x) = args.TO_EPOCH { builder.add_TO_EPOCH(x); }
        if let Some(x) = args.FROM_EPOCH { builder.add_FROM_EPOCH(x); }
        builder.add_NORAD_CAT_ID(args.NORAD_CAT_ID);
        builder.add_CLOSURE(args.CLOSURE);
        builder.add_RESIDUALS(args.RESIDUALS);
        builder.add_HAS_SCALE_COVARIANCE(args.HAS_SCALE_COVARIANCE);
        builder.add_SCALE_COVARIANCE(args.SCALE_COVARIANCE);
        builder.add_INITIAL(args.INITIAL);
        builder.add_TOWARDS(args.TOWARDS);
        builder.add_VELOCITY(args.VELOCITY);
        builder.add_WEIGHTING(args.WEIGHTING);
        builder.add_BSTAR_FROM_APRIORI(args.BSTAR_FROM_APRIORI);
        builder.add_FIT_BSTAR(args.FIT_BSTAR);
        builder.add_EPOCH_CHOICE(args.EPOCH_CHOICE);
        builder.finish()
    }

