/// `size_prefixed_root_as_erm_unchecked`.
#[inline]
pub fn size_prefixed_root_as_erm(buf: &[u8]) -> Result<ERM<'_>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::size_prefixed_root::<ERM>(buf)
}

/// Verifies, with the given options, that a buffer of bytes
/// contains a `ERM` and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_erm_unchecked`.
#[inline]
pub fn root_as_erm_with_opts<'b, 'o>(
    opts: &'o ::flatbuffers::VerifierOptions,
    buf: &'b [u8],
) -> Result<ERM<'b>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::root_with_opts::<ERM<'b>>(opts, buf)
}

/// Verifies, with the given verifier options, that a buffer of
/// bytes contains a size prefixed `ERM` and returns
/// it. Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_erm_unchecked`.
#[inline]
pub fn size_prefixed_root_as_erm_with_opts<'b, 'o>(
    opts: &'o ::flatbuffers::VerifierOptions,
    buf: &'b [u8],
) -> Result<ERM<'b>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::size_prefixed_root_with_opts::<ERM<'b>>(opts, buf)
}

/// Assumes, without verification, that a buffer of bytes contains a ERM and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid `ERM`.
#[inline]
pub unsafe fn root_as_erm_unchecked(buf: &[u8]) -> ERM<'_> {
    unsafe { ::flatbuffers::root_unchecked::<ERM>(buf) }
}

/// Assumes, without verification, that a buffer of bytes contains a size prefixed ERM and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid size prefixed `ERM`.
#[inline]
pub unsafe fn size_prefixed_root_as_erm_unchecked(buf: &[u8]) -> ERM<'_> {
    unsafe { ::flatbuffers::size_prefixed_root_unchecked::<ERM>(buf) }
}

pub const ERM_IDENTIFIER: &str = "$ERM";

#[inline]
pub fn erm_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, ERM_IDENTIFIER, false)
}

#[inline]
pub fn erm_size_prefixed_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, ERM_IDENTIFIER, true)
}

#[inline]
pub fn finish_erm_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<ERM<'a>>
) {
    fbb.finish(root, Some(ERM_IDENTIFIER));
}

#[inline]
pub fn finish_size_prefixed_erm_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<ERM<'a>>
) {
    fbb.finish_size_prefixed(root, Some(ERM_IDENTIFIER));
}
